<div class="field full"><label for="<?= $key ?>"><?= e($label) ?></label><?php if(!empty($row[$key])): ?><div class="existing-file"><?php if($kind==='image'): ?><img src="<?= e(media($row[$key])) ?>" alt="Current <?= e($label) ?>"><?php endif; ?><a class="text-link" href="<?= e(media($row[$key])) ?>" target="_blank" rel="noopener">View current file ↗</a><label class="checkbox"><input type="checkbox" name="remove_<?= $key ?>" <?= old('remove_'.$key)?'checked':'' ?>> Remove current file</label></div><?php endif; ?><input type="file" id="<?= $key ?>" name="<?= $key ?>" accept="<?= $kind==='pdf'?'application/pdf':'.jpg,.jpeg,.png,.webp' ?>"><small><?= $kind==='pdf'?'PDF only · Up to 10 MB':'JPG, PNG or WebP · Up to 5 MB' ?>. Leave empty to keep the current file.</small></div>
